#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25
# Replacement for the tail of night_queue_20261025.sh: pipelines on the desktop CPUs (18-19, split mode) took 48 min for a
# 60 s synthetic session, so the 1c + TASK 4 pipelines would never finish before the morning. New order: wait for the 1c
# batch ("BATCH DONE"), stop the old queue, run the TASK 4 Isaac families (still split), switch the host to off (all CPUs),
# then run every pipeline, then write "QUEUE DONE" to queue.log (the family loop and the scale runs wait for it).
set -u; cd "$(dirname "$0")/.."
LD=$HOME/fish_traces/night_20261025_final; mkdir -p "$LD"
log() { echo "[$(date +%T)] $*" | tee -a "$LD/queue.log"; }
EV=ros2:fish_msg_retain,ros2:fish_msg_release,ros2:fish_msg_type,ros2:fish_msg_stamp,ros2:fish_msg_ids
while ! grep -q "BATCH DONE" "$LD/night_runs.txt" 2>/dev/null; do sleep 60; done
pkill -f "^bash scripts/night_queue_20261025.sh"; sleep 2; pkill -f "^bash scripts/post_run_pipeline.sh"; pkill -f "^python3 ingest_pg.py"; pkill -f "^python3 model_improved_pg.py"
log "1b: old queue stopped after the 1c batch; TASK 4 Isaac runs start (split)"
for F in apriltag bi3d bi3d_freespace detectnet dnn_image_encoder dope ess image_proc nitros_bridge nvblox rtdetr segformer stereo_image_proc tensor_rt triton unet visual_slam; do
  log "task4 $F"
  IMG_OVERRIDE=fish-r2b-$F-fishdeterministic:latest REPS=1 MODES=lttng DEST_BASE="$LD/task4" SMOKE_TIMEOUT=1200 FISH_EXTRA_EVENTS=$EV \
    bash scripts/overhead_sweep_v8.sh "$F" > "$LD/task4_$F.log" 2>&1 || log "task4 $F rc=$?"
done
sudo -n /usr/local/sbin/fish-host-perf-mode off >> "$LD/queue.log" 2>&1; log "host off; pipelines on all CPUs"
for d in $(ls -d "$HOME"/fish_traces/fish_2* | sort | awk '$0 > "/home/tue037807/fish_traces/fish_20261025_195000"'); do
  S=$(basename "$d"); [ -f "$LD/pipelines_done.txt" ] && grep -q "^$S$" "$LD/pipelines_done.txt" && continue
  log "pipeline $S"; bash scripts/post_run_pipeline.sh "$S" "$HOME/fish_traces/analysis_$S" > "$LD/pipeline_$S.log" 2>&1 || log "pipeline $S FAILED"
  echo "$S" >> "$LD/pipelines_done.txt"
done
log "QUEUE DONE"
